import {db,$,rpc,invoke,run,notice,problem,localPhone,eye} from './client.js';
let mode='register',profile,application,token,unsubscribe;
const provinces=['بغداد','البصرة','نينوى','أربيل','السليمانية','دهوك','حلبجة','كركوك','ديالى','الأنبار','صلاح الدين','بابل','كربلاء','النجف','واسط','القادسية','ذي قار','ميسان','المثنى'];
$('province').append(new Option('اختر المحافظة',''),...provinces.map(p=>new Option(p,p)));
eye($('password'),$('eye'));
function setMode(value){mode=value;const creating=mode==='register';$('nameLabel').hidden=!creating;$('name').required=creating;$('confirmLabel').hidden=!creating;$('confirmPassword').required=creating;$('privacyLabel').hidden=!creating;$('privacy').required=creating;$('password').minLength=creating?8:1;$('password').autocomplete=creating?'new-password':'current-password';$('authTitle').textContent=creating?'إنشاء حساب كابتن':'دخول حسابك';$('authSubmit').textContent=creating?'إنشاء الحساب والمتابعة':'تسجيل الدخول';}
$('registerTab').onclick=()=>setMode('register');$('loginTab').onclick=()=>setMode('login');$('forgot').onclick=()=>{$('recoveryHelp').hidden=false;};
async function release(){const s=await rpc('tkt_captain_portal','settings');$('releaseStatus').textContent=s.available?'التطبيق متوفر الآن؛ حمّله وادخل بحسابك.':'التطبيق قريبًا على أندرويد. سجّل من هسه حتى نراجع طلبك.';$('download').hidden=!s.available;if(s.available&&/^https:\/\//.test(s.android_url))$('download').href=s.android_url;}
$('authForm').onsubmit=e=>{e.preventDefault();run(async()=>{if(mode==='register'&&$('password').value!==$('confirmPassword').value)problem('كلمتا السر مو متطابقتين.');const r=await invoke('taktooka-phone-auth',{op:mode,name:$('name').value.trim(),phone:$('phone').value,password:$('password').value,privacy_version:$('privacy').checked?'2026-10-11':null});$('password').value='';$('confirmPassword').value='';const session=await db.auth.refreshSession({refresh_token:r.refresh_token});if(session.error)throw session.error;await loadAccount();notice('تم تسجيل الدخول.');});};
async function loadAccount(){const {data:{user},error}=await db.auth.getUser();if(error||!user){$('auth').hidden=false;$('account').hidden=true;return;}const r=await db.from('tkt_profiles').select('name,phone,captain,blocked').eq('user_id',user.id).single();if(r.error)throw r.error;profile={...r.data,user_id:user.id};if(profile.blocked)throw new Error('ACCOUNT_BLOCKED');await rpc('tkt_captain_portal','join');application=await rpc('tkt_captain_registration','get');$('auth').hidden=true;$('account').hidden=false;$('accountName').textContent=profile.name;$('accountPhone').textContent=localPhone(profile.phone);const state=profile.captain?'approved':application?.status||'draft';$('applicationState').textContent={approved:'تمت الموافقة على حسابك ككابتن ✓',pending:'طلبك بانتظار مراجعة الإدارة',changes_required:'طلبك يحتاج إكمال بيانات',draft:'أكمل بياناتك وأرسل الطلب للمراجعة'}[state]||state;$('applicationReason').textContent=application?.reason||'';$('applicationForm').hidden=['approved','pending'].includes(state);for(const key of ['full_name','province','area','chassis','color','model'])$(key).value=application?.[key]||(key==='full_name'?profile.name:'');for(const slot of ['id_front','id_back'])$(slot+'_status').textContent=application?.documents?.[slot]?'تم حفظ الصورة ✓':'لم تُرفع الصورة';if('Notification'in window&&Notification.permission==='granted')await subscribe(false).catch(()=>{$('notifyStatus').textContent='تحتاج إعادة تفعيل إشعارات هذا المتصفح.';});}
async function save(){if($('full_name').value.trim().split(/\s+/).length<3)problem('اكتب اسمك الثلاثي كاملًا.');const data={phone:profile.phone};for(const key of ['full_name','province','area','chassis','color','model'])data[key]=$(key).value.trim();application=await rpc('tkt_captain_registration','save',data);for(const slot of ['id_front','id_back']){const file=$(slot).files[0];if(!file)continue;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>6291456)problem('اختار صورة JPG أو PNG أو WebP أقل من 6 ميگابايت.');const ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[file.type],path=profile.user_id+'/'+slot+'-'+crypto.randomUUID()+'.'+ext;const r=await db.storage.from('captain-documents').upload(path,file,{contentType:file.type,upsert:false});if(r.error)throw r.error;try{application=await rpc('tkt_captain_registration','save',{document:{slot,path}});}catch(e){await db.storage.from('captain-documents').remove([path]);throw e;}$(slot).value='';$(slot+'_status').textContent='تم حفظ الصورة ✓';}}
$('saveDraft').onclick=()=>run(async()=>{await save();notice('انحفظت بياناتك؛ تكدر ترجع تكمل لاحقًا.');});
$('applicationForm').onsubmit=e=>{e.preventDefault();run(async()=>{await save();await rpc('tkt_captain_registration','submit');await loadAccount();notice('تم إرسال طلبك للإدارة بنجاح.');});};
$('refresh').onclick=()=>run(async()=>{await loadAccount();await release();notice('تم تحديث حالة طلبك.');});
$('logout').onclick=()=>run(async()=>{if(token)await rpc('tkt_notification_action','unregister',{token}).catch(()=>{});await db.auth.signOut();profile=null;application=null;token=null;location.reload();});
async function subscribe(ask=true){if(!('Notification'in window)||!('serviceWorker'in navigator))problem('هذا المتصفح ما يدعم الإشعارات؛ افتح الرابط بمتصفح Chrome.');if(ask&&await Notification.requestPermission()!=='granted')problem('اسمح بالإشعارات من إعدادات المتصفح.');if(Notification.permission!=='granted')return;const [appApi,msgApi]=await Promise.all([import('https://www.gstatic.com/firebasejs/11.10.0/firebase-app.js'),import('https://www.gstatic.com/firebasejs/11.10.0/firebase-messaging.js')]);if(!await msgApi.isSupported())problem('هذا المتصفح ما يدعم إشعارات الخلفية.');const response=await fetch('../firebase-config.json');if(!response.ok)throw new Error('CONFIG');const config=await response.json();const app=appApi.getApps().find(a=>a.name==='taktooka-captains')||appApi.initializeApp(config,'taktooka-captains');const registration=await navigator.serviceWorker.register('./firebase-messaging-sw.js',{scope:'./',updateViaCache:'none'});await navigator.serviceWorker.ready;const messaging=msgApi.getMessaging(app);token=await msgApi.getToken(messaging,{vapidKey:config.vapidKey||undefined,serviceWorkerRegistration:registration});if(!token)throw new Error('NO_TOKEN');await rpc('tkt_notification_action','register',{token,platform:'web'});$('notifyStatus').textContent='إشعارات هذا المتصفح مفعّلة ✓';unsubscribe?.();unsubscribe=msgApi.onMessage(messaging,payload=>{notice(payload.data?.body||'تطبيق تكتوكة متوفر الآن.');release().catch(()=>{});});}
$('notify').onclick=()=>run(()=>subscribe());
run(async()=>{await release();await loadAccount();});
